//! Synthetic corpus v3 (05/10/2026): v2 families kept as they were, plus 19
//! families over realistic decisions with near-miss distractors (same words,
//! other subject), English queries over Portuguese decisions and file-led
//! tasks. Not human judgments, no calibration or providers. Each family has
//! PT, EN and distractor-worded queries. Holdout is family-wide.

pub struct Family {
    pub name: &'static str,
    pub positive: bool,
    pub holdout: bool,
    pub queries: [&'static str; 3],
    pub required: &'static [&'static str],
    pub partial: &'static [&'static str],
    pub files: &'static [&'static str],
}

